function utf8len(s: string): number {
  let n = 0
  for (const ch of s) {
    const c = ch.codePointAt(0) ?? 0
    n += c < 0x80 ? 1 : c < 0x800 ? 2 : c < 0x10000 ? 3 : 4
  }
  return n
}

/** A handoff file as the model would write it. omit = heading numbers (1..8) to leave out; tiny = under 800 bytes. */
function handoffText(o: { omit?: number[]; tiny?: boolean } = {}): string {
  const omit = o.omit ?? []
  const filler = o.tiny
    ? 'x.\n'
    : 'Real detail a fresh model needs: see /work/repo/src/index.ts and /work/repo/specs/compact.md for the facts. No secrets here.\n'.repeat(3)
  let out = '# Handoff: Test session (2026-10-12)\n'
  out += 'Read this whole file before doing anything else. It replaces the conversation history compaction removed.\n\n'
  HEADINGS.forEach((h, i) => {
    if (omit.includes(i + 1)) return
    out += `${h}\n${filler}\n`
  })
  return out
}

function norm(s: string): string {
  return s.replace(/\s+/g, ' ').trim()
}

/** All visible text of a drawn tree; an Svg (or anything with an `alt`) counts as its alt. */
function textOf(node: Any): string {
  if (node === null || node === undefined) return ''
  if (typeof node === 'string') return node
  if (Array.isArray(node)) return node.map(textOf).join('')
  if (typeof node === 'object') {
    const p = node.props ?? {}
    if (node.type === 'Svg' || typeof p.alt === 'string') return String(p.alt ?? '')
    if (node.type === 'Button') return String(p.label ?? '') + textOf(node.children)
    const kids = node.children
    if (Array.isArray(kids)) {
      const sep = node.type === 'Text' ? '' : '\n'
      return kids.map(textOf).join(sep)
    }
    return textOf(kids)
  }
  return String(node)
}

// ---- render recorder (conventions 3.1a): a ui.render hook may only call state.get, clock.now, ui.resolve ----
const RENDER_ALLOWED = new Set(['state.get', 'clock.now', 'ui.resolve', 'ui.render'])
type RenderLog = { on: boolean; calls: string[] }
/** Wrap `on` so every bottom hook that answers while log.on is set is recorded by name (a `$` call made by the plugin). */
function tapOn(on: Any, log: RenderLog): Any {
  const wrapped = (...args: Any[]): Any => {
    const i = args.length - 1
    const name = typeof args[0] === 'string' ? args[0] : '?'
    const fn = args[i]
    if (typeof fn === 'function') {
      const kind = fn.constructor?.name
      const w: Any =
        kind === 'AsyncGeneratorFunction'
          ? async function* (this: Any, ...a: Any[]) {
              if (log.on) log.calls.push(name)
              return yield* fn.apply(this, a)
            }
          : function (this: Any, ...a: Any[]) {
              if (log.on) log.calls.push(name)
              return fn.apply(this, a)
            }
      Object.defineProperty(w, 'length', { value: fn.length })
      args[i] = w
    }
    return on(...args)
  }
  return Object.assign(wrapped, on)
}
const disallowedIn = (calls: string[]): string[] => calls.filter(c => !RENDER_ALLOWED.has(c))

// Op-style calls on $ answer { value } (OpEventResult). Void ops answer { value: undefined }.
function op(on: Any, name: string, fn: (e: Any) => Any): void {
  on(name, ($: Any, e: Any, next: Any) => ({ value: fn(e) }))
}

// Register a hook at the bottom (the test's `on` sits beneath every plugin).
function bot(on: Any, name: string, fn: (e: Any, $: Any, next: Any) => Any): void {
  on(name, ($: Any, e: Any, next: Any) => fn(e, $, next))
}

